/**
 * The Termux CTF catalogue.
 *
 * This file is generated by the tool itself, not written by hand:
 *
 *     ctf export --challenges > src/data/termux-challenges.json
 *
 * so the website and the tool cannot drift apart. The format is versioned; see
 * docs/platform-integration.md in the learmux-ctf repository for the contract.
 *
 * Nothing here is a secret. The export carries briefings and hints but no
 * flags, because flags are derived from a seed that only exists on the
 * player's device.
 */

import raw from '../data/termux-challenges.json';

export type TermuxDifficulty = 'Easy' | 'Medium' | 'Hard';

export interface TermuxChallenge {
  id: string;
  slug: string;
  title: string;
  category: string;
  difficulty: TermuxDifficulty;
  points: number;
  objective: string;
  briefing: string;
  hints: string[];
}

interface Catalogue {
  format: string;
  version: string;
  challenges: TermuxChallenge[];
}

const catalogue = raw as Catalogue;

export const ctfRepo = 'https://github.com/apsideslabs/learmux-ctf';

/** Every challenge, in the order the tool lists them. */
export function allTermux(): TermuxChallenge[] {
  return catalogue.challenges;
}

export function termuxVersion(): string {
  return catalogue.version;
}

export function termuxTotal(): number {
  return catalogue.challenges.reduce((sum, c) => sum + c.points, 0);
}

export function termuxCount(): number {
  return catalogue.challenges.length;
}

/** Challenge counts and points, grouped by difficulty, in Easy to Hard order. */
export function termuxByDifficulty(): { difficulty: TermuxDifficulty; items: TermuxChallenge[] }[] {
  const order: TermuxDifficulty[] = ['Easy', 'Medium', 'Hard'];
  return order
    .map((difficulty) => ({
      difficulty,
      items: catalogue.challenges.filter((c) => c.difficulty === difficulty),
    }))
    .filter((group) => group.items.length > 0);
}

export function findTermux(slug: string): TermuxChallenge | undefined {
  return catalogue.challenges.find((c) => c.slug === slug);
}

/** The challenge before and after this one, for the pager at the foot of a page. */
export function termuxNeighbours(slug: string): {
  prev?: TermuxChallenge;
  next?: TermuxChallenge;
} {
  const list = catalogue.challenges;
  const i = list.findIndex((c) => c.slug === slug);
  if (i === -1) return {};
  return { prev: i > 0 ? list[i - 1] : undefined, next: i < list.length - 1 ? list[i + 1] : undefined };
}

/** The commands a player needs, used on the landing page and the play guide. */
export const installCommands = [
  'pkg install git',
  'git clone https://github.com/apsideslabs/learmux-ctf',
  'cd learmux-ctf',
  './install.sh',
];

export const coreCommands = [
  { cmd: 'ctf list', what: 'What is installed, and what you have captured.' },
  { cmd: 'ctf start <id>', what: 'Read the briefing and set the challenge up.' },
  { cmd: 'ctf check <id> <flag>', what: 'Hand in a flag you found.' },
  { cmd: 'ctf reset <id>', what: 'Put a challenge back to how it started.' },
];

export const extraCommands = [
  { cmd: 'ctf hint <id>', what: 'Reveal the next hint, one at a time.' },
  { cmd: 'ctf export', what: 'A receipt of your progress, to paste back here.' },
  { cmd: 'ctf doctor', what: 'Check that everything is where it should be.' },
];
